"""Storage interface. Swap LocalStorage for an S3 or Cloudinary backend later."""

import re
from typing import Protocol
from uuid import UUID

# Keys are generated by the server, never derived from user input. This pattern is a second
# line of defence: lowercase segments of [a-z0-9._-], no empty or dot-only segments.
_SEGMENT = r"[a-z0-9_-][a-z0-9._-]*"
KEY_PATTERN = re.compile(rf"^{_SEGMENT}(/{_SEGMENT})*$")


class StorageError(Exception):
    """Storage failed (disk full, permissions, backend unavailable...)."""


class InvalidKeyError(StorageError, ValueError):
    """A key that is malformed or would escape the storage root."""


class ObjectExistsError(StorageError):
    """Refusing to overwrite an existing object."""


class ObjectNotFoundError(StorageError):
    pass


def validate_key(key: str) -> str:
    if not KEY_PATTERN.fullmatch(key) or ".." in key.split("/"):
        raise InvalidKeyError("Invalid storage key.")
    return key


def item_key(user_id: UUID, item_id: UUID, filename: str) -> str:
    """users/<user>/items/<item>/<filename>, e.g. .../original.jpg or .../thumbnail.webp."""
    return validate_key(f"users/{user_id}/items/{item_id}/{filename}")


class Storage(Protocol):
    def save(self, key: str, data: bytes) -> None:
        """Store `data` under `key`. Raises ObjectExistsError if the key is taken."""

    def read(self, key: str) -> bytes:
        """Raises ObjectNotFoundError if missing."""

    def delete(self, key: str) -> None:
        """Remove `key`. Deleting a missing key is not an error (safe to retry)."""

    def exists(self, key: str) -> bool: ...
